cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv2d_fp16(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out,
    int K, int stride, int padding,
    int H_out, int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int n = idx / (C_out * H_out * W_out);
    int rem = idx % (C_out * H_out * W_out);
    int c_out = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    float sum = bias ? __half2float(bias[c_out]) : 0.0f;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int p = 0; p < K; ++p) {
            int h_in = h_start + p;
            if (h_in < 0 || h_in >= H_in) continue;
            for (int q = 0; q < K; ++q) {
                int w_in = w_start + q;
                if (w_in < 0 || w_in >= W_in) continue;

                int input_idx = ((n * C_in + c_in) * H_in + h_in) * W_in + w_in;
                int weight_idx = ((c_out * C_in + c_in) * K + p) * K + q;

                float a = __half2float(input[input_idx]);
                float b = __half2float(weight[weight_idx]);
                sum += a * b;
            }
        }
    }

    output[idx] = __float2half(sum);
}

torch::Tensor conv2d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias)
{
    const int stride = 4;
    const int padding = 2;

    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);
    const int C_out = weight.size(0);
    const int K = weight.size(2); // square kernel assumed

    const int H_out = (H_in + 2 * padding - K) / stride + 1;
    const int W_out = (W_in + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    const dim3 block(256);
    const dim3 grid((N * C_out * H_out * W_out + block.x - 1) / block.x);

    conv2d_fp16<<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr()) : nullptr,
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C_in, H_in, W_in,
        C_out,
        K, stride, padding,
        H_out, W_out
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    cudaDeviceSynchronize();

    return output;
}

