    def forward(ctx, input, weight, bias):
        return conv2d_ext.conv2d_fp16_forward(input, weight, bias)

    @staticmethod
    def symbolic(g, input, weight, bias):
        # Fallback for ONNX export
        return g.op("Conv", input, weight, bias,
                    strides_i=[4], pads_i=[2, 2, 2, 2])

