        self.weight = nn.Parameter(
            torch.randn(96, 3, 11, 11, dtype=torch.float16)
        )
        self.bias = nn.Parameter(
            torch.zeros(96, dtype=torch.float16)
        )

    def forward(self, x):
        return Conv2dCUDAFunction.apply(x, self.weight, self.bias)
